set challenge = $day23${"type":"mystery","visual":"paw-detail","version":"collettore-paw-v1","placeholder":false,"title":"A chi appartiene questa zampetta?","instructions":"Osserva da vicino la zampa: guarda la forma delle dita, gli artigli e il pelo. A quale dei quattro animali pensi appartenga?","image":"images/giochi/particolare-giorno-23-v2.png","image_credit":"Ricostruzione fotografica generata per il gioco.","options":["Scoiattolo","Volpe","Nutria","Riccio"],"correct_index":3,"sheet":{"image":"images/giochi/mammiferi-giorno-23.png","width":1536,"height":1024,"regions":[[0,0,768,512],[768,0,768,512],[0,512,768,512],[768,512,768,512]]},"animals":["Scoiattolo comune","Volpe","Nutria","Riccio europeo"],"scientific_names":["Sciurus vulgaris","Vulpes vulpes","Myocastor coypus","Erinaceus europaeus"],"paw_notes":["Lo scoiattolo usa dita mobili e artigli ricurvi per aggrapparsi alla corteccia e muoversi sui rami. Con le zampe anteriori può tenere e manipolare il cibo.","La volpe appoggia il peso sulle dita. Le sue impronte mostrano normalmente quattro dita con i segni degli artigli, disposte attorno a un cuscinetto centrale. Non hanno l’aspetto di una piccola mano.","La nutria ha grandi zampe posteriori parzialmente palmate, utili nel nuoto. Le zampe anteriori sono più piccole e non palmate: servono anche per afferrare e portare il cibo alla bocca.","Il riccio europeo ha cinque dita per zampa, con piccoli artigli. Le anteriori sono più larghe e compatte, mentre le posteriori sono più allungate. Nelle impronte a volte si vedono soltanto quattro dita."],"hint":"La zampa mostrata è piccola, con dita separate e artigli. Prova a immaginare l’animale mentre cammina tra le foglie e fruga a terra in cerca di cibo.","explanation":"È la zampa di un riccio europeo! Sotto il corpo coperto di aculei si nascondono zampe con dita e artigli, utili per camminare, frugare nella lettiera e scavare. Il riccio europeo ha cinque dita sia nelle zampe anteriori sia in quelle posteriori.\n\nIl numero delle dita, da solo, non basta per riconoscere un animale: anche altri mammiferi possono averne cinque. Per confrontare le zampe osserva insieme forma, proporzioni, artigli e presenza di membrane tra le dita. Le figure qui sotto mostrano tutti e quattro gli animali interi.","sources":[{"title":"Riccio europeo · Natural History Museum","url":"https://www.nhm.ac.uk/discover/hedgehog-erinaceus-europaeus.html"},{"title":"Tracce del riccio · Hedgehog Street","url":"https://www.hedgehogstreet.org/about-hedgehogs/tracks-and-signs/"},{"title":"Scoiattolo comune · The Wildlife Trusts","url":"https://www.wildlifetrusts.org/wildlife-explorer/mammals/red-squirrel"},{"title":"Volpe · Mammal Society","url":"https://mammal.org.uk/british-mammals/red-fox"},{"title":"Nutria · USGS","url":"https://nas.er.usgs.gov/queries/factsheet.aspx?speciesid=1089"}]}$day23$::jsonb
